<script setup lang="ts">
import{describeLiveFailure}from'~/features/live-core/gateway';
useSeoMeta({title:'教研治理｜语赞心声'});const gateway=useEntryLiveGateway();const state=ref<'loading'|'ready'|'empty'|'gap'|'error'>('loading');const versions=ref<Record<string,unknown>[]>([]);const failure=ref<ReturnType<typeof describeLiveFailure>|null>(null);async function load(){state.value='loading';try{const response=await gateway.researchVersions();versions.value=response.data.items;state.value=versions.value.length?'ready':'empty'}catch(error){failure.value=describeLiveFailure(error);state.value=failure.value.code==='PERSISTENCE_PENDING'?'gap':'error'}}await load();
</script>
<template><section class="research" aria-labelledby="research-title"><header class="research__hero"><div class="yx-shell"><p class="yx-kicker">RESEARCH GOVERNANCE · VERSIONED</p><h1 id="research-title">让每次改进有证据，<br>也有可追溯版本。</h1><p>视觉结构来自 VM B；课题、版本、教师姓名、覆盖率和审批结果均未迁入。</p></div></header><div class="yx-shell"><section v-if="state==='loading'" class="state" aria-live="polite"><h2>正在验证教研持久化……</h2></section><section v-else-if="state==='gap'" class="gap" role="status"><div><p class="yx-kicker">{{failure?.code}}</p><h2>教研空间已经有入口，<br>但还没有真实存储。</h2></div><aside><strong>{{failure?.message}}</strong><p>因此页面不展示 VM 中的课题名称、版本表、人员、百分比或“创建成功”。评审与发布操作保持禁用。</p><dl><div><dt>读取</dt><dd>HTTP 503</dd></div><div><dt>写入</dt><dd>禁用</dd></div><div><dt>AI 工具</dt><dd>另行读取 provider 状态</dd></div></dl></aside></section><section v-else-if="state==='error'" class="state" role="alert"><p class="yx-kicker">{{failure?.code||failure?.kind}}</p><h2>{{failure?.message}}</h2><NuxtLink v-if="failure?.kind==='unauthenticated'" to="/login?redirect=/research">重新登录</NuxtLink><NuxtLink v-else-if="failure?.kind==='permission'" to="/select-school">切换学校</NuxtLink><button v-else @click="load">重试</button></section><section v-else class="versions"><p class="yx-kicker">LIVE VERSIONS</p><h2>{{versions.length}} 个真实版本</h2><p v-if="state==='empty'">服务端返回空列表。</p><ol v-else><li v-for="(item,index) in versions" :key="String(item.id||index)"><b>{{String(index+1).padStart(2,'0')}}</b><span>{{String(item.title||item.name||'未命名版本')}}</span><code>{{String(item.status||'UNKNOWN')}}</code></li></ol></section><footer><button type="button" disabled>创建课题 · persistence pending</button><button type="button" disabled>提交评审 · persistence pending</button><button type="button" disabled>发布版本 · persistence pending</button></footer></div></section></template>
